 21	function fuzzyMatch(query: string, target: string): number {
 22	  const q = query.toLowerCase();
 23	  const t = target.toLowerCase();
 24	  if (t.includes(q)) return 100 + (q.length / t.length) * 50;
 25	  const words = t.split(/\s+/);
 26	  if (words.some((w) => w.startsWith(q))) return 80;
 27	  let qi = 0;
 28	  let score = 0;
 29	  for (let ti = 0; ti < t.length && qi < q.length; ti++) {
 30	    if (t[ti] === q[qi]) {
 31	      score += 10;
 32	      qi++;
 33	    }
 34	  }
 35	  return qi === q.length ? score : 0;
 36	}
